"""Weighted graph data structure with shortest path computation."""

import heapq
from collections import defaultdict


class WeightedGraph:
    """Undirected weighted graph supporting bandwidth, delay, and loss attributes on edges."""

    def __init__(self):
        self._adj = defaultdict(dict)
        self._nodes = set()

    def add_node(self, name):
        self._nodes.add(name)

    def add_edge(self, u, v, **attrs):
        self._nodes.add(u)
        self._nodes.add(v)
        self._adj[u][v] = attrs
        self._adj[v][u] = attrs

    def remove_edge(self, u, v):
        self._adj[u].pop(v, None)
        self._adj[v].pop(u, None)

    def neighbors(self, u):
        return list(self._adj[u].keys())

    def get_edge(self, u, v):
        return self._adj[u].get(v, {})

    def has_edge(self, u, v):
        return v in self._adj[u]

    @property
    def nodes(self):
        return list(self._nodes)

    def shortest_path(self, src, dst):
        """Dijkstra shortest path by hop count. Returns list of nodes or None."""
        if src == dst:
            return [src]
        if src not in self._nodes or dst not in self._nodes:
            return None

        dist = {src: 0}
        prev = {src: None}
        pq = [(0, src)]
        visited = set()

        while pq:
            d, u = heapq.heappop(pq)
            if u in visited:
                continue
            visited.add(u)
            if u == dst:
                break
            for v in self._adj[u]:
                if v not in visited:
                    nd = d + 1
                    if v not in dist or nd < dist[v]:
                        dist[v] = nd
                        prev[v] = u
                        heapq.heappush(pq, (nd, v))

        if dst not in prev:
            return None
        path = []
        cur = dst
        while cur is not None:
            path.append(cur)
            cur = prev[cur]
        path.reverse()
        return path

    def all_pairs_shortest_paths(self, node_subset=None):
        """Return dict of (src, dst) -> path for all pairs in node_subset."""
        nodes = node_subset if node_subset else list(self._nodes)
        result = {}
        for src in nodes:
            for dst in nodes:
                if src != dst:
                    p = self.shortest_path(src, dst)
                    if p:
                        result[(src, dst)] = p
        return result

