class Node:
    """Base node with interface bookkeeping and optional IP state."""

    def __init__(self, name, **params):
        self.name = name
        self.params = dict(params)
        self.intfs = {}
        self.ip = self.params.get("ip")

    def addIntf(self, intf, port=None):
        """Attach an interface to this node."""
        if port is None:
            port = len(self.intfs) + 1
        intf.port = port
        self.intfs[port] = intf
        return intf

    def intfList(self):
        """Return interfaces sorted by port."""
        return [self.intfs[port] for port in sorted(self.intfs)]

    @property
    def startup_time_ms(self):
        """Default startup time for namespace-backed nodes."""
        return 10.0

    def __repr__(self):
        return f"{self.__class__.__name__}({self.name!r})"


class Host(Node):
    """Emulated network host."""


