"""Link models for Mininet-style network simulation."""


def _coerce_delay(value):
    """Normalize delays to milliseconds."""
    if value is None:
        return 0.0
    if isinstance(value, str):
        stripped = value.strip().lower()
        if stripped.endswith("ms"):
            stripped = stripped[:-2]
        return float(stripped)
    return float(value)


def _coerce_float(value, default=0.0):
    if value is None:
        return float(default)
    if isinstance(value, str):
        return float(value.strip().rstrip("%"))
    return float(value)


class Intf:
    """Network interface bound to a node and a link."""

    def __init__(self, name, node, port=None, link=None):
        self.name = name
        self.node = node
        self.port = port
        self.link = link

    def __repr__(self):
        return f"Intf({self.name!r}, node={self.node.name!r}, port={self.port!r})"


class Link:
    """A bidirectional link between two nodes."""

    def __init__(self, node1, node2, port1=None, port2=None, **params):
        self.node1 = node1
        self.node2 = node2
        self.params = dict(params)
        self.bw = _coerce_float(self.params.get("bw", 1000.0), default=1000.0)
        self.delay = _coerce_delay(self.params.get("delay", 0.0))
        self.loss = _coerce_float(self.params.get("loss", 0.0), default=0.0)

        self.intf1 = self._make_intf(node1, port1)
        self.intf2 = self._make_intf(node2, port2)

    def _make_intf(self, node, port):
        if port is None:
            port = len(node.intfs) + 1
        intf = Intf(name=f"{node.name}-eth{port - 1}", node=node, port=port, link=self)
        node.addIntf(intf, port=port)
        return intf

    def other_node(self, node):
        if node == self.node1:
            return self.node2
        if node == self.node2:
            return self.node1
        return None

    def other_intf(self, intf):
        if intf == self.intf1:
            return self.intf2
        if intf == self.intf2:
            return self.intf1
        return None

    def endpoints(self):
        return self.node1, self.node2

    def connects(self, node):
        return node in (self.node1, self.node2)


class TCLink(Link):
    """Traffic-controlled link with explicit bandwidth, delay, and loss."""

