"""Topology builders for Mininet-style network simulation."""


class Topo:
    """Base topology storing declarative node and link definitions."""

    def __init__(self):
        self._hosts = {}
        self._switches = {}
        self._links = []

    def addHost(self, name, cls=None, **params):
        self._hosts[name] = {"cls": cls, "params": dict(params)}
        return name

    def addSwitch(self, name, cls=None, **params):
        self._switches[name] = {"cls": cls, "params": dict(params)}
        return name

    def addLink(self, node1, node2, cls=None, **params):
        self._links.append((node1, node2, cls, dict(params)))
        return (node1, node2)

    def hosts(self):
        return list(self._hosts)

    def switches(self):
        return list(self._switches)

    def links(self):
        return list(self._links)


class LinearTopo(Topo):
    """Linear chain of switches with one host attached to each switch."""

    def __init__(self, k=2, **link_params):
        super().__init__()
        previous_switch = None
        for index in range(1, k + 1):
            switch = self.addSwitch(f"s{index}")
            host = self.addHost(f"h{index}")
            self.addLink(host, switch, **link_params)
            if previous_switch is not None:
                self.addLink(previous_switch, switch, **link_params)
            previous_switch = switch


class SingleSwitchTopo(Topo):
    """Single switch connected to a set of hosts."""

    def __init__(self, k=2, **link_params):
        super().__init__()
        switch = self.addSwitch("s1")
        for index in range(1, k + 1):
            host = self.addHost(f"h{index}")
            self.addLink(host, switch, **link_params)


class TreeTopo(Topo):
    """Balanced tree of switches with hosts attached at switch leaves."""

    def __init__(self, depth=1, fanout=2, **link_params):
        super().__init__()
        if depth < 1:
            raise ValueError("depth must be at least 1")
        if fanout < 1:
            raise ValueError("fanout must be at least 1")
        self.depth = int(depth)
        self.fanout = int(fanout)
        self.link_params = dict(link_params)
        self._switch_index = 0
        self._host_index = 0
        self._build_subtree(parent_switch=None, remaining_depth=self.depth)

    def _next_switch_name(self):
        self._switch_index += 1
        return f"s{self._switch_index}"

    def _next_host_name(self):
        self._host_index += 1
        return f"h{self._host_index}"

    def _build_subtree(self, parent_switch, remaining_depth):
        switch = self.addSwitch(self._next_switch_name())
        if parent_switch is not None:
            self.addLink(parent_switch, switch, **self.link_params)

        if remaining_depth == 1:
            for _ in range(self.fanout):
                host = self.addHost(self._next_host_name())
                self.addLink(host, switch, **self.link_params)
            return

        for _ in range(self.fanout):
            self._build_subtree(parent_switch=switch, remaining_depth=remaining_depth - 1)

