"""Mininet-style network emulation engine."""

from itertools import combinations

from netsim.graph import WeightedGraph
from netsim.link import TCLink
from netsim.node import Controller, Host, OVSSwitch, Switch
from netsim.utils import compute_bottleneck_bw, generate_ip


class Mininet:
    """Simulation engine for host, switch, and link emulation."""

    def __init__(
        self,
        topo=None,
        host=Host,
        switch=OVSSwitch,
        controller=Controller,
        link=TCLink,
    ):
        self.topo = topo
        self.host_cls = host
        self.switch_cls = switch
        self.controller_cls = controller
        self.link_cls = link

        self.hosts = []
        self.switches = []
        self.controllers = []
        self.links = []
        self.name_to_node = {}
        self.graph = WeightedGraph()
        self._built = False

    def get(self, name):
        return self.name_to_node.get(name)

    def _resolve_node(self, node_or_name):
        if isinstance(node_or_name, str):
            node = self.get(node_or_name)
            if node is None:
                raise KeyError(f"unknown node: {node_or_name}")
            return node
        return node_or_name

    def _resolve_hosts(self, hosts=None):
        if hosts is None:
            return list(self.hosts)
        resolved = []
        for host in hosts:
            node = self._resolve_node(host)
            resolved.append(node)
        return resolved

    def addHost(self, name, cls=None, **params):
        host_cls = cls or self.host_cls
        host = host_cls(name, **params)
        self.hosts.append(host)
        self.name_to_node[name] = host
        self.graph.add_node(name)
        return host

    def addSwitch(self, name, cls=None, **params):
        switch_cls = cls or self.switch_cls
        switch = switch_cls(name, **params)
        self.switches.append(switch)
        self.name_to_node[name] = switch
        self.graph.add_node(name)
        return switch

    def addController(self, name, cls=None, **params):
        controller_cls = cls or self.controller_cls
        controller = controller_cls(name, **params)
        self.controllers.append(controller)
        self.name_to_node[name] = controller
        self.graph.add_node(name)
        return controller

    def addLink(self, node1, node2, cls=None, **params):
        node1_obj = self._resolve_node(node1)
        node2_obj = self._resolve_node(node2)
        link_cls = cls or self.link_cls
        link = link_cls(node1_obj, node2_obj, **params)
        self.links.append(link)
        self.graph.add_edge(
            node1_obj.name,
            node2_obj.name,
            link=link,
            bw=link.bw,
            delay=link.delay,
            loss=link.loss,
        )
        return link

    def build(self):
        if self._built or self.topo is None:
            return self

        if not self.controllers:
            self.addController("c0")

        for switch_name in self.topo.switches():
            spec = self.topo._switches[switch_name]
            self.addSwitch(switch_name, cls=spec["cls"], **spec["params"])

        for host_name in self.topo.hosts():
            spec = self.topo._hosts[host_name]
            self.addHost(host_name, cls=spec["cls"], **spec["params"])

        for node1, node2, cls, params in self.topo.links():
            self.addLink(node1, node2, cls=cls, **params)

        self._built = True
        return self

    def start(self):
        for index, host in enumerate(self.hosts, start=1):
            if not host.ip:
                host.ip = generate_ip(index)
        return self

    def _path_edges(self, path):
        edges = []
        for left, right in zip(path, path[1:]):
            edge = self.graph.get_edge(left, right)
            if not edge:
                return []
            edges.append(edge)
        return edges

    def ping(self, hosts=None):
        """Return loss percentage for host-to-host reachability."""
        selected = self._resolve_hosts(hosts)
        if len(selected) < 2:
            return 0.0

        total_pairs = 0
        lost_pairs = 0
        for src, dst in combinations(selected, 2):
            total_pairs += 1
            if not self.graph.shortest_path(src.name, dst.name):
                lost_pairs += 1

        if total_pairs == 0:
            return 0.0
        return (lost_pairs / total_pairs) * 100.0

    def pingAll(self):
        return self.ping(self.hosts)

    def iperf(self, hosts=None):
        """Simulate throughput between two hosts using the shortest path."""
        selected = self._resolve_hosts(hosts)
        if len(selected) < 2:
            return 0.0

        src, dst = selected[0], selected[1]
        path = self.graph.shortest_path(src.name, dst.name)
        if not path:
            return 0.0

        edges = self._path_edges(path)
        if not edges:
            return 0.0

        bottleneck = compute_bottleneck_bw([edge.get("bw", 0.0) for edge in edges])
        switch_hops = sum(
            1 for node_name in path if isinstance(self.name_to_node[node_name], Switch)
        )
        overhead_factor = (1.0 - Switch.FORWARDING_OVERHEAD) ** switch_hops
        return bottleneck * overhead_factor

    def avg_rtt(self, hosts=None):
        """Average round-trip time in milliseconds across reachable host pairs."""
        selected = self._resolve_hosts(hosts)
        if len(selected) < 2:
            return 0.0

        rtts = []
        for src, dst in combinations(selected, 2):
            path = self.graph.shortest_path(src.name, dst.name)
            if not path:
                continue
            total_delay = sum(edge.get("delay", 0.0) for edge in self._path_edges(path))
            rtts.append(2.0 * total_delay)

        if not rtts:
            return 0.0
        return sum(rtts) / len(rtts)

