"""Wireless link model with RSSI-aware throughput mapping."""

from netsim.link import TCLink
from netsim.utils import distance_2d
from netsim.wifi.propagation import received_signal_strength


class WirelessLink(TCLink):
    """Traffic-controlled link whose effective bandwidth depends on RSSI."""

    def __init__(self, node1, node2, **params):
        self.tx_gain_dbi = float(params.pop("tx_gain_dbi", 0.0))
        self.rx_gain_dbi = float(params.pop("rx_gain_dbi", 0.0))
        super().__init__(node1, node2, **params)
        if "bw" not in self.params:
            self.bw = self.effective_bw()
            self.params["bw"] = self.bw

    def _ap_like_node(self):
        if hasattr(self.node1, "tx_power_dbm") and hasattr(self.node1, "freq_hz"):
            return self.node1
        if hasattr(self.node2, "tx_power_dbm") and hasattr(self.node2, "freq_hz"):
            return self.node2
        return None

    def distance_m(self):
        if not hasattr(self.node1, "position") or not hasattr(self.node2, "position"):
            return 0.0
        return distance_2d(self.node1.position, self.node2.position)

    def rssi_dbm(self):
        ap = self._ap_like_node()
        if ap is None:
            return float("-inf")
        return received_signal_strength(
            tx_power_dbm=ap.tx_power_dbm,
            freq_hz=ap.freq_hz,
            distance_m=self.distance_m(),
            tx_gain_dbi=self.tx_gain_dbi,
            rx_gain_dbi=self.rx_gain_dbi,
            path_loss_exp=getattr(ap, "path_loss_exp", 3.0),
        )

    @staticmethod
    def bw_from_rssi(rssi_dbm):
        if rssi_dbm >= -50.0:
            return 54.0
        if rssi_dbm >= -60.0:
            return 48.0
        if rssi_dbm >= -65.0:
            return 36.0
        if rssi_dbm >= -70.0:
            return 24.0
        if rssi_dbm >= -75.0:
            return 12.0
        if rssi_dbm >= -80.0:
            return 6.0
        return 0.0

    def effective_bw(self):
        return self.bw_from_rssi(self.rssi_dbm())

