"""Service function chain models."""

from math import prod


class VNF:
    """Virtual network function with per-hop processing overhead."""

    def __init__(self, name, processing_delay_ms, overhead_pct):
        self.name = name
        self.processing_delay_ms = float(processing_delay_ms)
        self.overhead_pct = float(overhead_pct)

    @property
    def throughput_factor(self):
        return 1.0 - (self.overhead_pct / 100.0)


class ServiceFunctionChain:
    """Ordered chain of VNFs with shared link characteristics."""

    def __init__(self, vnfs=None, link_bw=1000.0, link_delay=0.0):
        self.vnfs = list(vnfs or [])
        self.link_bw = float(link_bw)
        self.link_delay = float(link_delay)

    @property
    def num_links(self):
        return len(self.vnfs) + 1

    def compute_throughput(self):
        factors = [vnf.throughput_factor for vnf in self.vnfs]
        return self.link_bw * prod(factors or [1.0])

    def compute_latency(self):
        processing = sum(vnf.processing_delay_ms for vnf in self.vnfs)
        return (self.num_links * self.link_delay) + processing

