"""Containernet extension for container-backed network emulation."""

from netsim.container import DockerHost
from netsim.net import Mininet
from netsim.node import Host
from netsim.utils import jains_fairness_index


class Containernet(Mininet):
    """Mininet extension with Docker-like hosts and SFC resource metrics."""

    def __init__(self, *args, **kwargs):
        super().__init__(*args, **kwargs)
        self.docker_hosts = []

    def addDocker(self, name, image, cls=None, **params):
        docker_cls = cls or DockerHost
        docker_host = super().addHost(name, cls=docker_cls, image=image, **params)
        self.docker_hosts.append(docker_host)
        return docker_host

    def compute_resource_fairness(self):
        shares = [host.cpu_shares for host in self.docker_hosts]
        return jains_fairness_index(shares)

    def total_nodes(self):
        return len(self.hosts) + len(self.switches)

    def startup_overhead_ratio(self):
        return DockerHost("ratio-probe", image="probe").startup_time_ms / Host(
            "host-probe"
        ).startup_time_ms

