from collections import OrderedDict

from netsim.net import Mininet
from netsim.node import Switch
from netsim.topo import Topo


class P4MatchActionTable:
    """Exact-match table with priority-based rule resolution."""

    def __init__(self, name, match_fields, max_size=1024):
        self.name = name
        self.match_fields = list(match_fields)
        self.max_size = int(max_size)
        self._rules = []
        self._sequence = 0

    def add_rule(self, match_dict, action_name, action_params=None, priority=0):
        if self.size() >= self.max_size:
            raise ValueError(f"table {self.name} is at capacity")
        rule = {
            "match": dict(match_dict),
            "action_name": action_name,
            "action_params": dict(action_params or {}),
            "priority": int(priority),
            "sequence": self._sequence,
        }
        self._sequence += 1
        self._rules.append(rule)
        return rule

    def lookup(self, packet_headers):
        best_rule = None
        for rule in self._rules:
            if all(packet_headers.get(field) == value for field, value in rule["match"].items()):
                if best_rule is None:
                    best_rule = rule
                    continue
                if rule["priority"] > best_rule["priority"]:
                    best_rule = rule
                    continue
                if (
                    rule["priority"] == best_rule["priority"]
                    and rule["sequence"] < best_rule["sequence"]
                ):
                    best_rule = rule
        return best_rule

    def delete_rule(self, match_dict):
        for index, rule in enumerate(self._rules):
            if rule["match"] == dict(match_dict):
                del self._rules[index]
                return True
        return False

    def size(self):
        return len(self._rules)

    def clear(self):
        self._rules.clear()


class P4Parser:
    """Parser that extracts header fields from fixed byte offsets."""

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs)

    def _required_length(self):
        if not self.header_defs:
            return 0
        return max(offset + length for offset, length in self.header_defs.values())

    def is_valid(self, packet_data):
        return len(packet_data) >= self._required_length()

    def parse(self, packet_data):
        if not self.is_valid(packet_data):
            raise ValueError("packet shorter than parser header definition")
        headers = {}
        for field_name, (offset, length) in self.header_defs.items():
            headers[field_name] = bytes(packet_data[offset : offset + length])
        return headers


class P4Deparser:
    """Deparser that rebuilds packet bytes from header fields and payload."""

    def __init__(self, header_defs):
        self.header_defs = dict(header_defs)

    @staticmethod
    def _normalize_field_value(value, length):
        if isinstance(value, int):
            return int(value).to_bytes(length, byteorder="big", signed=False)
        if isinstance(value, str):
            value = value.encode("ascii")
        value_bytes = bytes(value)
        if len(value_bytes) == length:
            return value_bytes
        if len(value_bytes) > length:
            return value_bytes[:length]
        return value_bytes + (b"\x00" * (length - len(value_bytes)))

    def deparse(self, headers, payload):
        header_length = 0
        if self.header_defs:
            header_length = max(offset + length for offset, length in self.header_defs.values())
        packet = bytearray(header_length)
        for field_name, (offset, length) in self.header_defs.items():
            raw_value = headers.get(field_name, b"\x00" * length)
            packet[offset : offset + length] = self._normalize_field_value(raw_value, length)
        return bytes(packet) + bytes(payload)


class P4Counter:
    """Counter array tracking per-index packet and byte statistics."""

    def __init__(self, name, size):
        self.name = name
        self.size_limit = int(size)
        self._packet_counts = [0 for _ in range(self.size_limit)]
        self._byte_counts = [0 for _ in range(self.size_limit)]

    def increment(self, index, packet_bytes):
        self._validate_index(index)
        byte_count = packet_bytes if isinstance(packet_bytes, int) else len(packet_bytes)
        self._packet_counts[index] += 1
        self._byte_counts[index] += int(byte_count)

    def read(self, index):
        self._validate_index(index)
        return self._packet_counts[index], self._byte_counts[index]

    def reset(self, index=None):
        if index is None:
            for idx in range(self.size_limit):
                self._packet_counts[idx] = 0
                self._byte_counts[idx] = 0
            return
        self._validate_index(index)
        self._packet_counts[index] = 0
        self._byte_counts[index] = 0

    def total_packets(self):
        return sum(self._packet_counts)

    def total_bytes(self):
        return sum(self._byte_counts)

    def _validate_index(self, index):
        if index < 0 or index >= self.size_limit:
            raise IndexError(f"counter index out of range: {index}")


class P4Switch(Switch):
    """Switch with programmable parser, tables, counters, and deparser."""

    def __init__(self, name, program=None, **params):
        super().__init__(name, **params)
        self.program = program
        self.tables = OrderedDict()
        self.counters = OrderedDict()
        self.parser = None
        self.deparser = None

    def add_table(self, table):
        self.tables[table.name] = table
        return table

    def add_counter(self, counter):
        self.counters[counter.name] = counter
        return counter

    def set_parser(self, parser):
        self.parser = parser
        return parser

    def set_deparser(self, deparser):
        self.deparser = deparser
        return deparser

    def process_packet(self, packet_data):
        if self.parser is not None:
            if not self.parser.is_valid(packet_data):
                raise ValueError("invalid packet for parser")
            headers = self.parser.parse(packet_data)
            payload_offset = max(
                offset + length for offset, length in self.parser.header_defs.values()
            ) if self.parser.header_defs else 0
            payload = bytes(packet_data[payload_offset:])
        else:
            headers = {}
            payload = bytes(packet_data)

        dropped = False
        for table in self.tables.values():
            rule = table.lookup(headers)
            if rule is None:
                continue
            if self._apply_action(rule, headers, packet_data):
                dropped = True
                break

        if dropped:
            return b""
        if self.deparser is not None:
            return self.deparser.deparse(headers, payload)
        if self.parser is not None:
            return packet_data[:payload_offset] + payload
        return bytes(packet_data)

    def _apply_action(self, rule, headers, packet_data):
        action_name = rule["action_name"]
        action_params = rule["action_params"]
        counter_name = action_params.get("counter")
        counter_index = int(action_params.get("index", 0))
        if counter_name:
            counter = self.get_counter(counter_name)
            if counter is None:
                raise KeyError(f"unknown counter {counter_name!r}")
            counter.increment(counter_index, packet_data)

        if action_name == "drop":
            return True
        if action_name == "set_field":
            headers[action_params["field"]] = action_params["value"]
        elif action_name == "set_fields":
            for field_name, value in action_params.get("values", {}).items():
                headers[field_name] = value
        elif action_name in {"forward", "count", "nop"}:
            return False
        return False

    def get_table(self, name):
        return self.tables.get(name)

    def get_counter(self, name):
        return self.counters.get(name)

    @property
    def pipeline_latency_us(self):
        return 0.5 * len(self.tables)


class P4Topology(Topo):
    """Linear chain of P4 switches with attached hosts."""

    def __init__(self, num_switches, num_hosts_per_switch, **link_params):
        super().__init__()
        self.num_switches = int(num_switches)
        self.num_hosts_per_switch = int(num_hosts_per_switch)
        previous_switch = None
        for switch_index in range(1, self.num_switches + 1):
            switch_name = self.addP4Switch(f"s{switch_index}")
            for host_index in range(1, self.num_hosts_per_switch + 1):
                host_name = self.addHost(f"h{switch_index}_{host_index}")
                self.addLink(host_name, switch_name, **link_params)
            if previous_switch is not None:
                self.addLink(previous_switch, switch_name, **link_params)
            previous_switch = switch_name

    def addP4Switch(self, name, **params):
        return self.addSwitch(name, cls=P4Switch, **params)


class P4MulticastGroup:
    """Collection of output ports for multicast replication."""

    def __init__(self, group_id, ports):
        self.group_id = group_id
        self.ports = list(ports)

    def replicate(self, packet_data):
        return [(port, bytes(packet_data)) for port in self.ports]

    def add_port(self, port):
        if port not in self.ports:
            self.ports.append(port)

    def remove_port(self, port):
        if port in self.ports:
            self.ports.remove(port)


def forwarding_rate_mbps(net, src_name, dst_name, table_count_per_switch=1, packet_size_bytes=1500):
    """Estimate forwarding rate through a P4 topology using pipeline latency as overhead."""
    base_rate = net.iperf([net.get(src_name), net.get(dst_name)])
    total_switches = sum(
        1 for switch in net.switches if isinstance(switch, P4Switch)
    )
    total_latency_us = total_switches * 0.5 * table_count_per_switch
    serialization_us = (packet_size_bytes * 8.0) / max(base_rate, 1e-9)
    efficiency = serialization_us / (serialization_us + total_latency_us)
    return base_rate * efficiency

