"""SDN controller simulation with flow-rule management."""

import heapq
from collections import defaultdict


class FlowRule:
    """OpenFlow-style flow entry with timeout and match semantics."""

    def __init__(self, match_fields, actions, priority=100, idle_timeout=0, hard_timeout=0):
        self.match_fields = dict(match_fields)
        self.actions = list(actions)
        self.priority = int(priority)
        self.idle_timeout = float(idle_timeout)
        self.hard_timeout = float(hard_timeout)
        self.packet_count = 0
        self.byte_count = 0
        self.installed_at = 0.0

    def is_expired(self, current_time, last_matched_time):
        reference_time = self.installed_at if last_matched_time is None else last_matched_time
        if self.idle_timeout > 0 and (current_time - reference_time) >= self.idle_timeout:
            return True
        if self.hard_timeout > 0 and (current_time - self.installed_at) >= self.hard_timeout:
            return True
        return False

    def matches(self, packet_headers):
        return all(packet_headers.get(field) == value for field, value in self.match_fields.items())

    def record_match(self, byte_count=0):
        self.packet_count += 1
        self.byte_count += int(byte_count)


class FlowTable:
    """Per-switch flow table with capacity and timeout handling."""

    def __init__(self, switch_name, capacity=4096):
        self.switch_name = switch_name
        self.capacity = int(capacity)
        self._rules = []
        self._last_matched_times = {}

    def install(self, rule):
        if self.size() >= self.capacity and not any(
            existing.match_fields == rule.match_fields and existing.priority == rule.priority
            for existing in self._rules
        ):
            return False

        self._rules = [
            existing
            for existing in self._rules
            if not (
                existing.match_fields == rule.match_fields and existing.priority == rule.priority
            )
        ]
        self._rules.append(rule)
        return True

    def remove(self, match_fields):
        removed = 0
        remaining = []
        for rule in self._rules:
            if rule.match_fields == dict(match_fields):
                removed += 1
                self._last_matched_times.pop(rule, None)
                continue
            remaining.append(rule)
        self._rules = remaining
        return removed

    def lookup(self, packet_headers):
        best_rule = None
        for rule in self._rules:
            if not rule.matches(packet_headers):
                continue
            if best_rule is None or rule.priority > best_rule.priority:
                best_rule = rule
        if best_rule is not None:
            byte_count = (
                packet_headers.get("size_bytes")
                or packet_headers.get("byte_count")
                or packet_headers.get("packet_len")
                or 0
            )
            best_rule.record_match(byte_count=byte_count)
            self._last_matched_times[best_rule] = packet_headers.get("current_time", 0.0)
        return best_rule

    def evict_expired(self, current_time, last_matched_times):
        evicted = 0
        surviving_rules = []
        for rule in self._rules:
            last_seen = self._resolve_last_matched_time(rule, last_matched_times)
            if rule.is_expired(current_time=current_time, last_matched_time=last_seen):
                evicted += 1
                self._last_matched_times.pop(rule, None)
                continue
            surviving_rules.append(rule)
        self._rules = surviving_rules
        return evicted

    def _resolve_last_matched_time(self, rule, last_matched_times):
        if last_matched_times is None:
            return self._last_matched_times.get(rule, rule.installed_at)
        if rule in last_matched_times:
            return last_matched_times[rule]
        rule_id = id(rule)
        if rule_id in last_matched_times:
            return last_matched_times[rule_id]
        rule_key = tuple(sorted(rule.match_fields.items()))
        if rule_key in last_matched_times:
            return last_matched_times[rule_key]
        return self._last_matched_times.get(rule, rule.installed_at)

    def size(self):
        return len(self._rules)

    def stats(self):
        return [(rule, rule.packet_count, rule.byte_count) for rule in self._rules]

    def clear(self):
        self._rules.clear()
        self._last_matched_times.clear()

    def utilization(self):
        if self.capacity <= 0:
            return 0.0
        return self.size() / self.capacity


class SDNController:
    """Base SDN controller with topology discovery and path-rule management."""

    def __init__(self, name):
        self.name = name
        self.topology = defaultdict(dict)
        self.flow_tables = {}
        self.host_ips = {}
        self.ip_to_host = {}
        self.link_ports = {}

    def add_switch(self, switch_name):
        self.flow_tables.setdefault(switch_name, FlowTable(switch_name))
        self.topology.setdefault(switch_name, {})
        return self.flow_tables[switch_name]

    def add_link(self, node1, node2, weight=1):
        self.topology[node1][node2] = float(weight)
        self.topology[node2][node1] = float(weight)

    def remove_link(self, node1, node2):
        self.topology[node1].pop(node2, None)
        self.topology[node2].pop(node1, None)

    def topology_discovery(self, net):
        self.topology = defaultdict(dict)
        self.flow_tables = {}
        self.host_ips = {}
        self.ip_to_host = {}
        self.link_ports = {}

        for switch in net.switches:
            self.add_switch(switch.name)

        for host in net.hosts:
            self.topology.setdefault(host.name, {})
            if host.ip:
                self.host_ips[host.name] = host.ip
                self.ip_to_host[host.ip] = host.name

        for link in net.links:
            node1, node2 = link.endpoints()
            self.add_link(node1.name, node2.name, weight=1)
            self.link_ports[(node1.name, node2.name)] = link.intf1.port
            self.link_ports[(node2.name, node1.name)] = link.intf2.port

    def compute_path(self, src, dst):
        if src == dst:
            return [src]
        if src not in self.topology or dst not in self.topology:
            return []

        distances = {src: 0.0}
        previous = {src: None}
        queue = [(0.0, src)]
        visited = set()

        while queue:
            distance, node = heapq.heappop(queue)
            if node in visited:
                continue
            visited.add(node)
            if node == dst:
                break
            for neighbor, weight in self.topology[node].items():
                candidate = distance + weight
                if candidate < distances.get(neighbor, float("inf")):
                    distances[neighbor] = candidate
                    previous[neighbor] = node
                    heapq.heappush(queue, (candidate, neighbor))

        if dst not in previous:
            return []

        path = []
        current = dst
        while current is not None:
            path.append(current)
            current = previous[current]
        return list(reversed(path))

    def compute_all_paths(self):
        paths = {}
        hosts = list(self.host_ips)
        for src in hosts:
            for dst in hosts:
                if src == dst:
                    continue
                path = self.compute_path(src, dst)
                if path:
                    paths[(src, dst)] = path
        return paths

    def install_path_rules(self, path, src_ip, dst_ip, priority=100):
        installed = 0
        for index, node_name in enumerate(path[:-1]):
            if node_name not in self.flow_tables:
                continue
            next_hop = path[index + 1]
            output_port = self.link_ports.get((node_name, next_hop), 0)
            rule = FlowRule(
                match_fields={"src_ip": src_ip, "dst_ip": dst_ip},
                actions=[{"type": "output", "port": output_port}],
                priority=priority,
            )
            if self.flow_tables[node_name].install(rule):
                installed += 1
        return installed

    def total_rules_installed(self):
        return sum(table.size() for table in self.flow_tables.values())

    def handle_link_failure(self, node1, node2):
        self.remove_link(node1, node2)
        for table in self.flow_tables.values():
            table.clear()

        reinstalled = 0
        for (src, dst), path in self.compute_all_paths().items():
            reinstalled += self.install_path_rules(path, self.host_ips[src], self.host_ips[dst])
        return reinstalled


class ReactiveController(SDNController):
    """Reactive controller that installs rules on packet-in events."""

    def __init__(self, name):
        super().__init__(name)
        self.packet_in_count = 0

    def handle_packet_in(self, switch_name, packet_headers):
        self.packet_in_count += 1
        flow_table = self.flow_tables.get(switch_name)
        if flow_table is not None and flow_table.lookup(packet_headers):
            return 0

        src_ip = packet_headers["src_ip"]
        dst_ip = packet_headers["dst_ip"]
        src_name = self.ip_to_host.get(src_ip)
        dst_name = self.ip_to_host.get(dst_ip)
        if src_name is None or dst_name is None:
            return 0
        path = self.compute_path(src_name, dst_name)
        if not path:
            return 0
        return self.install_path_rules(path, src_ip, dst_ip)


class ProactiveController(SDNController):
    """Proactive controller that pre-installs all host-to-host rules."""

    rule_install_time_ms = 0.1

    def __init__(self, name):
        super().__init__(name)
        self._last_install_count = 0

    def install_all_rules(self, hosts_with_ips):
        if isinstance(hosts_with_ips, dict):
            mapping = dict(hosts_with_ips)
        else:
            mapping = {}
            for entry in hosts_with_ips:
                if hasattr(entry, "name") and hasattr(entry, "ip"):
                    mapping[entry.name] = entry.ip
                else:
                    name, ip = entry
                    mapping[name] = ip

        self.host_ips.update(mapping)
        self.ip_to_host.update({ip: name for name, ip in mapping.items()})
        for table in self.flow_tables.values():
            table.clear()

        installed = 0
        for src_name, src_ip in mapping.items():
            for dst_name, dst_ip in mapping.items():
                if src_name == dst_name:
                    continue
                path = self.compute_path(src_name, dst_name)
                if not path:
                    continue
                installed += self.install_path_rules(path, src_ip, dst_ip)

        self._last_install_count = installed
        return installed

    def total_install_time(self):
        return self._last_install_count * self.rule_install_time_ms
